// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCoupon, getCoupon, deleteCoupon } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

// The instant the created coupon carries; GET /:id must return this same point in time.
const EXPIRATION_DATE = "2027-06-30T12:00:00.000Z";

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const couponCode = uniqueSuffix("TESTBOT-GET-A1");

    // Accepted request that creates the coupon the later steps address.
    const couponsPostResponse = await createCoupon(client, headers, couponCode, 201, 15, EXPIRATION_DATE);
    expect(couponsPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(couponsPostResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsPostResponse, "response.discountPercent"), 'discountPercent').toBe(15);

    // The route serves the caller's own coupon, expirationDate included.
    const couponsCouponsGetResponse = await getCoupon(client, headers, getResponseValue(couponsPostResponse, "response.id"), 200);
    expect(couponsCouponsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(couponsCouponsGetResponse, "response.id"), 'id').toBe(getResponseValue(couponsPostResponse, "response.id"));
    expect(getResponseValue(couponsCouponsGetResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsCouponsGetResponse, "response.discountPercent"), 'discountPercent').toBe(15);
    expect(
        new Date(String(getResponseValue(couponsCouponsGetResponse, "response.expirationDate"))).getTime(),
        'expirationDate'
    ).toBe(new Date(EXPIRATION_DATE).getTime());

    // An id no coupon has is refused.
    const coupons999999999GetResponse = await getCoupon(client, headers, 999999999, 404);
    expect(coupons999999999GetResponse.statusCode, 'status code').toBe(404);
    expect(getResponseValue(coupons999999999GetResponse, "response"), 'not found message').toBe("Coupon not found.");

    // A non-numeric id is refused.
    const abcGetResponse = await getCoupon(client, headers, "abc", 400);
    expect(abcGetResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(abcGetResponse, "response"), 'invalid id message').toBe("Invalid coupon ID.");

    // A method the route does not implement is refused. This is NOT cleanup: the coupons API
    // exposes no DELETE route, so the coupon this test created cannot be removed by the test.
    const couponsCouponsDeleteResponse = await deleteCoupon(client, headers, getResponseValue(couponsPostResponse, "response.id"), 405);
    expect(couponsCouponsDeleteResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(couponsCouponsDeleteResponse, "response"), 'method not allowed message').toBe("Method not allowed.");
});
